<?php
declare(strict_types=1);
namespace NHK\Tests\Support;
use NHK\Core\Contracts\Authority\AuthorityRepository;
use NHK\Core\Domain\Authority\AuthorityEntity;
use NHK\Core\Authority\Exception\{AuthorityRevisionConflict,StableKeyCollision};
final class InMemoryAuthorityRepository implements AuthorityRepository { private array $items=[]; public function findByCanonicalId(string $id):?AuthorityEntity{return $this->items[$id]??null;} public function findByStableKey(string $type,string $key):?AuthorityEntity{foreach($this->items as $e)if($e->entityType===$type&&$e->stableKey===$key)return $e;return null;} public function create(AuthorityEntity $e):AuthorityEntity{if($this->findByStableKey($e->entityType,$e->stableKey))throw new StableKeyCollision('Stable key collision.');return $this->items[$e->canonicalId]=$e;} public function update(AuthorityEntity $e,int $expectedRevision):AuthorityEntity{$old=$this->findByCanonicalId($e->canonicalId);if(!$old||$old->revision!==$expectedRevision)throw new AuthorityRevisionConflict('Authority revision conflict.');$n=new AuthorityEntity($e->canonicalId,$e->entityType,$e->stableKey,$e->canonicalName,$e->schemaVersion,$e->payload,$e->state,$expectedRevision+1,$old->createdAt,'now',$e->retiredAt);return $this->items[$e->canonicalId]=$n;} public function listByType(string $type):array{return array_values(array_filter($this->items,fn(AuthorityEntity $e)=>$e->entityType===$type));} }
